import parity from './workflow.parity.json';
import {
  canAdminAssign,
  canAdminUnassign,
  isLocked,
  isStaffed,
  staffHandlerName,
  workflowKey,
  type WorkflowKey,
  type WorkflowRequest,
} from '../workflow';

// workflow.parity.json was generated by running the web app's own dprWorkflowStatus.js over every combination of
// server workflow, status, owner, linked report and generation markers: [request, key, canAssign, canUnassign, locked].
// Regenerate it if the web rules change; the port in ../workflow.ts must then follow.
type Row = [WorkflowRequest, WorkflowKey, boolean, boolean, boolean];

describe('workflow rules match the web app', () => {
  const rows = parity.cases as unknown as Row[];

  it('covers every workflow key, status and owner shape', () => {
    expect(rows.length).toBeGreaterThan(500);
    const keys = new Set(rows.map((r) => r[1]));
    expect([...keys].sort()).toEqual(['ca_validation', 'generated', 'initiated', 'pending', 'preparation', 'rejected']);
  });

  it.each(['key', 'assign', 'unassign', 'locked'] as const)('agrees with the web on %s for every combination', (field) => {
    const wrong = rows.filter(([req, key, assign, unassign, locked]) => {
      if (field === 'key') return workflowKey(req) !== key;
      if (field === 'assign') return canAdminAssign(req) !== assign;
      if (field === 'unassign') return canAdminUnassign(req) !== unassign;
      return isLocked(req) !== locked;
    });
    expect(wrong.map((r) => JSON.stringify(r[0]))).toEqual([]);
  });

  it('agrees when the report is passed separately', () => {
    for (const [req, report, key, assign, unassign, locked] of parity.withReport as unknown as [
      WorkflowRequest, { validation_status: string }, WorkflowKey, boolean, boolean, boolean,
    ][]) {
      expect(workflowKey(req, report)).toBe(key);
      expect(canAdminAssign(req, report)).toBe(assign);
      expect(canAdminUnassign(req, report)).toBe(unassign);
      expect(isLocked(req, report)).toBe(locked);
    }
  });

  it('names the handler like the web does', () => {
    for (const [req, name] of parity.names as unknown as [WorkflowRequest, string][]) {
      expect(staffHandlerName(req)).toBe(name);
    }
  });
});

describe('what the admin is offered', () => {
  const wf = (key: WorkflowKey) => ({ key, label: key });

  it('offers assign to an open request nobody owns', () => {
    const r = { status: 'open', workflow: wf('pending') };
    expect([canAdminAssign(r), canAdminUnassign(r), isLocked(r)]).toEqual([true, false, false]);
  });

  it('offers only unassign once someone owns it', () => {
    const r = { status: 'assigned', assignedTo: { _id: 'u1', name: 'Suresh' }, workflow: wf('initiated') };
    expect([canAdminAssign(r), canAdminUnassign(r), isLocked(r)]).toEqual([false, true, false]);
  });

  it.each(['ca_validation', 'generated'] as const)('offers nothing while %s', (key) => {
    const r = { status: 'completed', claimedBy: { _id: 'u1' }, workflow: wf(key) };
    expect([canAdminAssign(r), canAdminUnassign(r), isLocked(r)]).toEqual([false, false, true]);
  });

  it('treats an owned request whose staff account was deleted as unowned', () => {
    // populate() turns a deleted user into null, so nobody is shown as handler and assign is offered again.
    const r = { status: 'open', assignedTo: null, workflow: wf('pending') };
    expect(canAdminAssign(r)).toBe(true);
  });

  it('derives the stage itself when the server sends no workflow', () => {
    expect(workflowKey({ status: 'open' })).toBe('pending');
    expect(workflowKey({ status: 'claimed', claimedBy: 'u1' })).toBe('initiated');
    expect(workflowKey({ status: 'completed', generationStartedAt: '2026-01-01' })).toBe('preparation');
    expect(workflowKey({ status: 'completed', reportId: { validation_status: 'under_review' } })).toBe('ca_validation');
    expect(workflowKey({ status: 'completed', reportId: { validation_status: 'approved' } })).toBe('generated');
    expect(workflowKey({ status: 'completed', reportId: { validation_status: 'rejected' } })).toBe('rejected');
  });

  it('never calls an open request staffed, even with a stale owner', () => {
    expect(isStaffed({ status: 'open', assignedTo: 'u1' })).toBe(false);
    expect(isStaffed(null)).toBe(false);
  });

  it('returns nothing for a missing request', () => {
    expect([canAdminAssign(null), canAdminUnassign(undefined), staffHandlerName(null)]).toEqual([false, false, '']);
  });
});
